"""Market sync: pushes the market quantity of every changed product to the vendor."""
from datetime import datetime, timedelta

from hbstock.market.feed import build_feed

# the market's sales day starts at 06:00, when the full sync runs
MARKET_DAY_START = timedelta(hours=6)


class SyncService:
    def __init__(self, repo, client, settings, on_synced=None, clock=None):
        self.repo = repo
        self.client = client
        self.settings = settings
        self.on_synced = on_synced
        self.clock = clock or datetime.now
        self.last_sent = {}
        # sku -> market day of its last restock
        self.restocked_on = {}

    def run(self, full=False):
        skus = [p.sku for p in self.repo.products()] if full else self.repo.take_dirty()
        if full:
            self.repo.take_dirty()
        products = [self.repo.product(sku) for sku in skus]
        lines, sent = build_feed(products, self.settings)
        # nothing to tell the market about a product whose announced quantity did not move
        changed = [line for line, sku in zip(lines, sent) if full or self.last_sent.get(sku) != sent[sku]]
        if not full:
            # the market alerts every waiting customer on each restock and penalises a product
            # restocked twice in one market day, so a second restock waits for the 06:00 full sync
            changed = [line for line in changed if not self._second_restock_today(line, sent)]
        if not changed:
            return {"transfer": None, "lines": 0, "skus": []}
        transfer = self.client.push(changed)
        pushed = [line.split("\t", 1)[0] for line in changed]
        today = self._market_day()
        for sku in pushed:
            if self._is_restock(sku, sent):
                self.restocked_on[sku] = today
            self.last_sent[sku] = sent[sku]
        if self.on_synced:
            self.on_synced()
        return {"transfer": transfer.transfer_id, "lines": transfer.lines, "skus": pushed}

    def _market_day(self):
        return (self.clock() - MARKET_DAY_START).date()

    def _is_restock(self, sku, sent):
        """Off sale (last announced 0) and now announced with units."""
        return self.last_sent.get(sku) == 0 and sent[sku] > 0

    def _second_restock_today(self, line, sent):
        sku = line.split("\t", 1)[0]
        return self._is_restock(sku, sent) and self.restocked_on.get(sku) == self._market_day()

